CREATE TABLE "MenuItemModifierGroup" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"menuItemId" TEXT NOT NULL,"modifierGroupId" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "MenuItemModifierGroup_pkey" PRIMARY KEY ("id"));
